/* =====================================================
   FONT CARLITO UNTUK pdfMake (cadangan, kompatibel metrik dengan
   Calibri) -- di-generate dari paket npm @fontsource/carlito
   (subset Latin, WOFF dikonversi ke TTF dengan fonttools), lalu
   di-embed sebagai base64 langsung ke virtual file system (vfs)
   pdfMake. TIDAK ada dokumen PDF di aplikasi ini yang memakai
   font 'Carlito' saat ini -- disiapkan sebagai cadangan saja,
   digabung (bukan menimpa) dengan window.MONTSERRAT_VFS/FONTS di
   lib/fonts-montserrat.js, lihat siapPdf() di kejadian.html.
   ===================================================== */

window.KEJADIAN_VFS = {
  "Carlito-Regular.ttf": "",
  "Carlito-Bold.ttf": "",
  "Carlito-Italic.ttf": "",
  "Carlito-BoldItalic.ttf": "",
};

window.KEJADIAN_FONTS = {
  Carlito: {
    normal: "Carlito-Regular.ttf",
    bold: "Carlito-Bold.ttf",
    italics: "Carlito-Italic.ttf",
    bolditalics: "Carlito-BoldItalic.ttf"
  }
};
